blocks.code:
@use 'sass:color';
@use 'sass:map';

$brand: #3451b2;
$space: (
  sm: 0.5rem,
  md: 1rem,
  lg: 1.5rem
);

.card {
  color: $brand;
  padding: map.get($space, md);
  &__title { margin-bottom: map.get($space, sm); }
  &:hover { border-color: color.scale($brand, $lightness: -12%); }
}

