blocks.code:
$space: (sm: 0.5rem, md: 1rem);

@mixin focus-ring($color) {
  &:focus-visible {
    outline: 3px solid $color;
    outline-offset: 2px;
  }
}

@each $name, $value in $space {
  .gap-#{$name} { gap: $value; }
}

.button { @include focus-ring(#3451b2); }

%surface {
  border: 1px solid currentColor;
  border-radius: 0.5rem;
}

.notice {
  @extend %surface;
  color: #17406b;
}

@mixin panel($background) {
  border: 1px solid currentColor;
  background: $background;
}

.alert {
  @include panel(#fff1f0);
}

